const crypto = require('crypto');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');

const _raw = $input.first().json;
const corpus = (_raw && _raw.data && _raw.data.signals) ? _raw.data : _raw;
const signals = corpus.signals || [];

const norm = (v) => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const slug = (s) => String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

const seen = new Set();
const out = [];
let duplicates = 0;

for (const s of signals) {
  const canonical = JSON.stringify({
    u: s.source_url || '',
    c: s.claim || '',
    t: s.signal_type || ''
  });
  const content_hash = sha256(canonical);

  if (seen.has(content_hash)) { duplicates++; continue; }
  seen.add(content_hash);

  out.push({
    json: {
      evidence_id: s.id,
      arm: corpus.arm,
      status: 'normalised',
      content_hash,
      signal_type: s.signal_type || 'unclassified',
      source_name: s.source_name || null,
      source_url: s.source_url || null,
      title: s.title || null,
      claim: s.claim || null,
      evidence_grade: s.grade || 'E3',
      retrieved_at: corpus.acquired_at,
      direction: s.direction || 'neutral',
      buyers: norm(s.buyers).map(slug),
      producers: norm(s.producers).map(slug),
      titles: norm(s.titles),
      genres: norm(s.genres).map(slug),
      worlds: norm(s.worlds).map(slug),
      engines: norm(s.engines).map(slug),
      format: s.format ? slug(s.format) : null,
      territory: s.territory || null,
      route_type: s.route_type || null,
      metric_name: s.metric_name || null,
      metric_value: (s.metric_value !== undefined) ? s.metric_value : null,
      interpretation: s.interpretation || null,
      legal_flag: s.legal_flag || null,
      conflict_note: s.conflict_note || null,
      source_ip: s.source_ip || null
    }
  });
}

return [{ json: {
  stage: 'WF-10',
  generated_at: new Date().toISOString(),
  input_signal_count: signals.length,
  normalised_count: out.length,
  duplicates_dropped: duplicates,
  hash_algorithm: 'sha256',
  records: out.map(o => o.json)
} }];
